import Foundation
import Testing

@testable import PyawwCore

@Suite("Word segmentation (mmdt port)")
struct SegmentationTests {
    private static let vectorsURL = TestPaths.fixtures
        .appendingPathComponent("segmentation/vectors.tsv")

    /// `input<TAB>expected` rows generated by scripts/generate_seg_vectors.py.
    private static func vectors() throws -> [(input: String, expected: String)] {
        let content = try String(contentsOf: vectorsURL, encoding: .utf8)
        var rows: [(String, String)] = []
        for line in content.split(separator: "\n", omittingEmptySubsequences: false) {
            if line.isEmpty || line.hasPrefix("#") { continue }
            let parts = line.split(separator: "\t", maxSplits: 1, omittingEmptySubsequences: false)
            guard parts.count == 2 else { continue }
            rows.append((String(parts[0]), String(parts[1])))
        }
        return rows
    }

    @Test("matches the Python reference vectors exactly")
    func referenceVectors() throws {
        let segmenter = try MMDTSegmenter()
        let rows = try Self.vectors()
        #expect(rows.count >= 200)
        var failures: [String] = []
        for row in rows where segmenter.segment(row.input) != row.expected {
            failures.append("input:    \(row.input)\nexpected: \(row.expected)\ngot:      \(segmenter.segment(row.input))")
        }
        if !failures.isEmpty {
            Issue.record("""
            \(failures.count)/\(rows.count) vector mismatches:
            \(failures.prefix(6).joined(separator: "\n----\n"))
            """)
        }
    }

    @Test("output stays an in-order subsequence; deletions limited to the documented special set")
    func preservesCharacters() throws {
        let segmenter = try MMDTSegmenter()
        // Characters upstream's preprocessing deliberately replaces with
        // spaces (`removeSpecial` + `[-:/]` rules in preprocess.py/cleaner.py).
        // Everything else must survive, in order.
        let deletable: Set<Character> = [
            "~", "^", "*", "_", "+", "=", "<", ">", "[", "]", "{", "}", "|", "\\",
            "…", "“", "”", "‘", "’", "「", "」", "『", "』", "\"", "'", "#", "(", ")",
            ".", "-", ":", "/",
        ]
        for row in try Self.vectors() {
            let got = segmenter.segment(row.input)
            let inputChars = Array(row.input.filter { !$0.isWhitespace })
            let outputChars = Array(got.filter { !$0.isWhitespace })

            var matched = 0
            for ch in inputChars where matched < outputChars.count && outputChars[matched] == ch {
                matched += 1
            }
            #expect(matched == outputChars.count, "not an in-order subsequence: \(row.input) → \(got)")

            var counts: [Character: Int] = [:]
            for ch in inputChars { counts[ch, default: 0] += 1 }
            for ch in outputChars { counts[ch, default: 0] -= 1 }
            let unexpected = counts.filter { $0.value > 0 && !deletable.contains($0.key) }.keys
            #expect(unexpected.isEmpty, "deleted \(unexpected.sorted()) from \(row.input) → \(got)")
        }
    }

    @Test("segmenting is idempotent")
    func idempotent() throws {
        let segmenter = try MMDTSegmenter()
        for row in try Self.vectors() {
            let once = segmenter.segment(row.input)
            let twice = segmenter.segment(once)
            #expect(twice == once, "input: \(row.input)")
        }
    }

    @Test("empty and whitespace-only input")
    func emptyInput() throws {
        let segmenter = try MMDTSegmenter()
        #expect(segmenter.segment("") == "")
        #expect(segmenter.segment("   ") == "")
        #expect(segmenter.segment("\n\t") == "")
    }

    @Test("de-space only joins Myanmar word characters")
    func despaceRules() throws {
        let segmenter = try MMDTSegmenter()
        #expect(segmenter.despaceMyanmar("က ခ ဂ") == "ကခဂ")
        #expect(segmenter.despaceMyanmar("၁၂ ၃၄") == "၁၂ ၃၄")        // digits keep their space
        #expect(segmenter.despaceMyanmar("ပါ။ ဒီ") == "ပါ။ ဒီ")        // ။ keeps its space
        #expect(segmenter.despaceMyanmar("မြန်မာ ၁၂၃") == "မြန်မာ ၁၂၃")  // letter↔digit untouched
        #expect(segmenter.despaceMyanmar("abc ဒီ") == "abc ဒီ")        // Latin is not Myanmar
    }

    @Test("keeps ၊ ။ , ? ! attached to the preceding word")
    func punctuationKept() throws {
        let segmenter = try MMDTSegmenter()
        #expect(segmenter.segment("မြန်မာ၊ ပြီးတော့") == "မြန်မာ၊ ပြီးတော့")
        #expect(segmenter.segment("ကျွန်တော်။ ကျွန်တော်") == "ကျွန်တော်။ ကျွန်တော်")
        #expect(segmenter.segment("ကျွန်တော်? ဟုတ်လား!") == "ကျွန်တော်? ဟုတ် လား!")
    }
}
